from __future__ import annotations

from dataclasses import dataclass

from errors.codes import docs_anchor_for_code
from errors.families import is_known_family
from errors.severity import normalize_severity


@dataclass(frozen=True)
class ErrorDefinition:
    code: str
    family: str
    title: str
    default_detail: str
    severity: str
    default_breakpoint: str
    retryable: bool
    user_action_required: bool
    recommended_fix: str
    http_status: int
    docs_anchor: str


def _entry(
    code: str,
    *,
    family: str,
    title: str,
    detail: str,
    severity: str,
    breakpoint: str,
    retryable: bool,
    user_action_required: bool,
    recommended_fix: str,
    http_status: int,
) -> ErrorDefinition:
    if not is_known_family(family):
        raise ValueError(f"Unknown error family: {family}")
    return ErrorDefinition(
        code=code,
        family=family,
        title=title,
        default_detail=detail,
        severity=normalize_severity(severity),
        default_breakpoint=breakpoint,
        retryable=retryable,
        user_action_required=user_action_required,
        recommended_fix=recommended_fix,
        http_status=http_status,
        docs_anchor=docs_anchor_for_code(code),
    )


