ERROR_REGISTRY: dict[str, ErrorDefinition] = {item.code: item for item in _DEFINITIONS}


def get_error_definition(code: str) -> ErrorDefinition:
    try:
        return ERROR_REGISTRY[code]
    except KeyError as exc:
        raise KeyError(f"Unknown Mission Control error code: {code}") from exc


def iter_error_definitions() -> tuple[ErrorDefinition, ...]:
    return tuple(ERROR_REGISTRY.values())
